<script setup>
import {computed,ref,watch} from 'vue';import {Head,Link,useForm,router} from '@inertiajs/vue3';
import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';import {useExamContext} from '../exam-context';
const props=defineProps({questions:Object,groups:Array,subjects:Array,filters:Object});const {context,base,page}=useExamContext();const open=ref(false),editing=ref(null),action=ref(null),groupOpen=ref(false),groupEditing=ref(null),groupList=ref(false);
const skills={listening:'Nghe',reading:'Đọc',writing:'Viết',speaking:'Nói'};const kinds={mcq:'Trắc nghiệm',essay:'Tự luận',speaking:'Bài nói / ghi âm'};
const defaults=()=>({part:5,subject_id:'',question_group_id:'',kind:'mcq',skill:'reading',content:'',options:{A:'',B:'',C:'',D:''},correct_option:'A',explanation:'',difficulty:'medium',max_points:1});const form=useForm(defaults());
const group=useForm({part:3,subject_id:'',title:'',passage:'',media_path:''});const filter=ref({search:props.filters.search||'',part:props.filters.part||'',skill:props.filters.skill||'',subject_id:props.filters.subject_id||''});
watch(()=>form.skill,skill=>{if(context.value.slug==='vstep')form.kind=skill==='writing'?'essay':skill==='speaking'?'speaking':'mcq';});
const availableGroups=computed(()=>props.groups.filter(group=>(context.value.slug!=='toeic'||Number(group.part)===Number(form.part))&&(context.value.slug!=='course'||Number(group.subject_id)===Number(form.subject_id))));
function show(question=null){editing.value=question;form.clearErrors();Object.assign(form,defaults(),question?{...Object.fromEntries(Object.keys(defaults()).map(key=>[key,question[key]??defaults()[key]])),options:{A:'',B:'',C:'',D:'',...question.options}}:{});open.value=true;}
function save(){form.submit(editing.value?'put':'post',base.value+'/questions'+(editing.value?'/'+editing.value.id:''),{preserveScroll:true,onSuccess:()=>open.value=false});}
function showGroup(item=null){groupList.value=false;groupEditing.value=item;group.clearErrors();Object.assign(group,item?{part:item.part,subject_id:item.subject_id||'',title:item.title||'',passage:item.passage||'',media_path:item.media_path||''}:{part:3,subject_id:'',title:'',passage:'',media_path:''});groupOpen.value=true;}
function saveGroup(){group.submit(groupEditing.value?'put':'post',base.value+'/question-groups'+(groupEditing.value?'/'+groupEditing.value.id:''),{onSuccess:()=>groupOpen.value=false});}
const owner=item=>page.props.auth.user.role==='admin'||item.created_by===page.props.auth.user.id;
</script>
<template><Head :title="'Ngân hàng câu hỏi · '+context.name"/><AppLayout><div class="page-heading"><div><h1>Ngân hàng câu hỏi {{context.name}}</h1><p>Học liệu riêng cho {{context.name}}. {{context.slug==='course'?'Chia theo từng môn học.':context.slug==='vstep'?'Quản lý đủ bốn kỹ năng.':'Cấu trúc Part 1–7.'}}</p></div><div class="actions"><button class="secondary" @click="groupList=true">Nhóm tư liệu</button><button @click="show()">+ Thêm câu hỏi</button></div></div><div class="card"><form class="filter-row" @submit.prevent="router.get(base+'/questions',filter,{preserveState:true,replace:true})"><input v-model="filter.search" placeholder="Tìm nội dung câu hỏi…" aria-label="Tìm câu hỏi"/><select v-if="context.slug==='toeic'" v-model="filter.part" aria-label="Lọc Part"><option value="">Tất cả Part</option><option v-for="part in 7" :key="part" :value="part">Part {{part}}</option></select><select v-if="context.slug==='vstep'" v-model="filter.skill" aria-label="Lọc kỹ năng"><option value="">Tất cả kỹ năng</option><option v-for="(label,key) in skills" :key="key" :value="key">{{label}}</option></select><select v-if="context.slug==='course'" v-model="filter.subject_id" aria-label="Lọc môn học"><option value="">Tất cả môn</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.code}} · {{subject.name}}</option></select><button>Lọc</button></form><div class="tablewrap"><table><thead><tr><th>Mã</th><th>{{context.slug==='toeic'?'Part':context.slug==='vstep'?'Kỹ năng':'Môn học'}}</th><th>Nội dung</th><th>Dạng / điểm</th><th>Thao tác</th></tr></thead><tbody><tr v-for="question in questions.data" :key="question.id"><td>#{{question.id}}</td><td>{{context.slug==='toeic'?'Part '+question.part:context.slug==='vstep'?skills[question.skill]:subjects.find(subject=>subject.id===question.subject_id)?.name||'—'}}</td><td class="table-title">{{question.content}}</td><td>{{kinds[question.kind]}}<small class="cell-meta">{{question.max_points}} điểm</small></td><td><div v-if="owner(question)" class="actions"><button class="secondary" @click="show(question)">Sửa</button><button class="secondary" @click="action={url:base+'/questions/'+question.id,title:'Xóa câu hỏi',message:'Xóa câu hỏi #'+question.id+'? Câu đã dùng trong đề sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!questions.data.length"><td colspan="5" class="empty-state">Chưa có câu hỏi phù hợp. Thêm câu hỏi đầu tiên cho phân hệ này.</td></tr></tbody></table></div><div class="pagination"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url">← Trước</Link><span>Trang {{questions.current_page}} / {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url">Tiếp →</Link></div></div>
<AppModal :open="open" :title="(editing?'Sửa':'Thêm')+' câu hỏi · '+context.name" wide :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><div class="formgrid"><div v-if="context.slug==='toeic'" class="field"><label for="q-part">Part</label><select id="q-part" v-model.number="form.part"><option v-for="part in 7" :key="part" :value="part">Part {{part}}</option></select></div><div v-if="context.slug==='vstep'" class="field"><label for="q-skill">Kỹ năng</label><select id="q-skill" v-model="form.skill"><option v-for="(label,key) in skills" :key="key" :value="key">{{label}}</option></select></div><div v-if="context.slug==='course'" class="field"><label for="q-subject">Môn học</label><select id="q-subject" v-model="form.subject_id" required><option value="" disabled>Chọn môn</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.name}}</option></select></div><div class="field"><label for="q-kind">Dạng câu hỏi</label><select id="q-kind" v-model="form.kind" :disabled="context.slug!=='course'"><option value="mcq">Trắc nghiệm</option><option v-if="context.slug!=='toeic'" value="essay">Tự luận</option><option v-if="context.slug!=='toeic'" value="speaking">Bài nói / ghi âm</option></select></div><div class="field"><label for="q-group">Nhóm tư liệu</label><select id="q-group" v-model="form.question_group_id"><option value="">Không có nhóm</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{group.title}}</option></select></div><div class="field"><label for="q-points">Điểm tối đa</label><input id="q-points" type="number" min="0.1" max="100" step="0.1" v-model.number="form.max_points" required/></div></div><div class="field"><label for="q-content">Nội dung / yêu cầu bài làm</label><textarea id="q-content" v-model="form.content" required rows="4" maxlength="10000"/></div><template v-if="form.kind==='mcq'"><div class="formgrid"><div v-for="key in ['A','B','C','D']" :key="key" class="field"><label :for="'q-option-'+key">Phương án {{key}}</label><input :id="'q-option-'+key" v-model="form.options[key]" :required="['A','B'].includes(key)"/></div></div><div class="field"><label for="q-correct">Đáp án đúng</label><select id="q-correct" v-model="form.correct_option"><option v-for="key in ['A','B','C','D']" :key="key" :value="key">{{key}}</option></select></div></template><p v-else class="notice">Bài {{form.kind==='essay'?'tự luận':'nói'}} được giáo viên chấm trong mục Bài làm & kết quả.</p><div class="field"><label for="q-explanation">Giải thích / hướng dẫn chấm</label><textarea id="q-explanation" v-model="form.explanation" rows="2"/></div><div class="field"><label for="q-difficulty">Độ khó</label><select id="q-difficulty" v-model="form.difficulty"><option value="easy">Dễ</option><option value="medium">Trung bình</option><option value="hard">Khó</option></select></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing">Lưu câu hỏi</button></div></form></AppModal>
<AppModal :open="groupList" title="Nhóm tư liệu" wide @close="groupList=false"><button @click="showGroup()">+ Thêm nhóm tư liệu</button><div class="modal-list"><div v-for="item in groups" :key="item.id"><p><strong>{{item.title}}</strong><small class="cell-meta">#{{item.id}}{{context.slug==='toeic'?' · Part '+item.part:''}}</small></p><div v-if="owner(item)" class="actions"><button class="secondary" @click="showGroup(item)">Sửa</button><button class="secondary" @click="action={url:base+'/question-groups/'+item.id,title:'Xóa nhóm tư liệu',message:'Xóa nhóm '+item.title+'? Nhóm đã có câu hỏi sẽ được giữ lại.'}">Xóa</button></div></div><p v-if="!groups.length" class="muted">Chưa có nhóm tư liệu.</p></div></AppModal>
<AppModal :open="groupOpen" :title="groupEditing?'Sửa nhóm tư liệu':'Thêm nhóm tư liệu'" :busy="group.processing" @close="groupOpen=false"><form @submit.prevent="saveGroup"><FormErrors :errors="group.errors"/><div class="field"><label for="group-title">Tên nhóm</label><input id="group-title" v-model="group.title" required/></div><div v-if="context.slug==='toeic'" class="field"><label for="group-part">Part</label><select id="group-part" v-model.number="group.part"><option v-for="part in 7" :key="part" :value="part">Part {{part}}</option></select></div><div v-if="context.slug==='course'" class="field"><label for="group-subject">Môn học</label><select id="group-subject" v-model="group.subject_id" required><option value="" disabled>Chọn môn</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{subject.name}}</option></select></div><div class="field"><label for="group-passage">Đoạn đọc / transcript</label><textarea id="group-passage" v-model="group.passage" rows="5"/></div><div class="field"><label for="group-media">Đường dẫn âm thanh / hình ảnh nội bộ</label><input id="group-media" v-model="group.media_path" placeholder="audio/conversation.mp3"/></div><div class="modal-actions"><button type="button" class="secondary" @click="groupOpen=false">Hủy</button><button :disabled="group.processing">Lưu nhóm tư liệu</button></div></form></AppModal><ConfirmAction :action="action" @close="action=null"/></AppLayout></template>
